import json

def parse(value, default):
    return json.loads(value) if isinstance(value,str) and value.strip() else (value or default)

def handler(context):
    icp=parse(context.get_input('icp_json'),{})
    supplied=parse(context.get_input('settings_json'),{})
    settings={'max_candidates':6,'minimum_score':55,'minimum_fit':40,'minimum_proof':40,'minimum_sources':2,'half_life_days':90}
    if set(supplied)-set(settings): raise ValueError('Unknown advanced setting')
    settings.update(supplied)
    for k,v in settings.items():
        if type(v) not in (int,float): raise ValueError('Settings must be numbers')
    if type(settings['max_candidates']) is not int or not 1<=settings['max_candidates']<=10: raise ValueError('Sample size must be an integer from 1 to 10')
    if type(settings['minimum_sources']) is not int or not 2<=settings['minimum_sources']<=8: raise ValueError('Minimum sources must be an integer from 2 to 8')
    if not 1<=settings['half_life_days']<=730: raise ValueError('Half-life must be 1 to 730 days')
    if any(not 0<=settings[k]<=100 for k in ['minimum_score','minimum_fit','minimum_proof']): raise ValueError('Score thresholds must be 0 to 100')
    dimensions=['fit','proof','insight','usefulness']
    if 'weights' not in icp:
        icp={**icp,'brief':context.get_input('focus') or 'GTM operators and agencies to feature and learn from',
             'weights':{k:icp.get(k+'_weight',0) for k in dimensions},
             'dimensions':{k:icp.get(k+'_rubric','') for k in dimensions},
             'freshness_half_life_days':settings['half_life_days'],'lookback_days':180}
    icp['settings']=settings
    icp['freshness_half_life_days']=settings['half_life_days']
    weights=icp.get('weights',{})
    if set(weights)!=set(dimensions): raise ValueError('ICP requires four explicit weights')
    weights={k:float(weights[k]) for k in dimensions}
    if any(v<=0 or v>1 for v in weights.values()): raise ValueError('Weights must be positive and <=1')
    total=sum(weights.values()); icp['weights']={k:v/total for k,v in weights.items()}
    brief=' '.join(str(context.get_input('focus') or icp.get('brief','')).lower().split())
    scope=brief+'\n'+json.dumps(settings,sort_keys=True)
    memory=parse(context.get_input('memory_json'),{})
    feedback=parse(context.get_input('feedback_json'),[])
    if memory and memory.get('scope')!=scope: raise ValueError('Memory belongs to another ICP; use blank memory for a new brief')
    memory=memory or {'version':1,'scope':scope,'icp':icp,'arms':{},'seen':{},'processed_feedback':[],'ratings':{}}
    icp=memory.get('icp',icp)
    processed=set(memory['processed_feedback']); applied=0; ignored=[]
    if not isinstance(feedback,list): raise ValueError('Feedback must be an array')
    for row in feedback:
        fid=row.get('feedback_id'); cid=row.get('candidate_id'); rating=row.get('rating')
        if not fid or fid in processed:
            ignored.append('missing_or_duplicate_feedback_id'); continue
        if cid not in memory['seen'] or type(rating) not in (int,float) or rating not in (0,1):
            raise ValueError('Feedback must name a previously researched candidate and have rating 0 or 1')
        lane=memory['seen'][cid]['lane']; arm=memory['arms'].setdefault(lane,{'alpha':1,'beta':1,'reviews':0})
        old=memory.setdefault('ratings',{}).get(cid)
        if old:
            previous=memory['arms'][old['lane']]
            previous['alpha']-=old['rating']; previous['beta']-=1-old['rating']; previous['reviews']-=1
        arm['alpha']+=rating; arm['beta']+=1-rating; arm['reviews']+=1
        memory['ratings'][cid]={'rating':rating,'lane':lane}
        processed.add(fid); applied+=1
    memory['processed_feedback']=sorted(processed)
    return {'icp_json':json.dumps(icp),'memory_json':json.dumps(memory),'seen_json':json.dumps(list(memory['seen'].keys())),
            'feedback_applied':applied,'feedback_ignored':ignored,'learning_state':'REVIEW_LEARNING' if processed else 'COLD_START',
            'memory_mode':'Explicit carry-forward from the previous local run record; no external storage or cached sourcing'}

import json

def handler(context):
    raw=context.get_input('candidates_json')
    rows=json.loads(raw) if isinstance(raw,str) else raw
    if not isinstance(rows,list): raise ValueError('Discovery must return an array')
    seen=set(); results=[]; rejected=[]
    icp=context.get_input('icp_json') or {}
    if isinstance(icp,str): icp=json.loads(icp)
    limit=icp.get('settings',{}).get('max_candidates',6)
    allowed=[x.strip() for x in icp.get('allowed_entity_types','person,agency,company').split(',')]
    organizations=set()
    for row in rows[:12]:
        if row.get('entity_type') not in allowed:
            rejected.append({'name':row.get('name'),'reason':'Wrong entity type for this ICP'});continue
        url=str(row.get('profile_url') or row.get('discovery_url') or '').strip()
        rest=url.split('://',1)[-1].split('?',1)[0].split('#',1)[0]
        host=rest.split('/',1)[0].lower().removeprefix('www.')
        if not url.startswith(('https://','http://')) or '.' not in host or '@' in host or not str(row.get('name','')).strip():
            rejected.append({'name':row.get('name'),'reason':'Missing identity URL or name'}); continue
        identity=(host+'/'+rest.split('/',1)[1] if '/' in rest else host).rstrip('/').lower()
        org=str(row.get('domain','')).lower().removeprefix('www.').rstrip('/')
        shared_hosts={'linkedin.com','youtube.com','github.com','medium.com','substack.com','gtmskills.com'}
        if org in shared_hosts: org=''
        if row.get('entity_type')!='person': identity=org or identity
        if identity in seen: continue
        if org and org in organizations:
            rejected.append({'name':row.get('name'),'reason':'Organization already represented in this sample'});continue
        if org:organizations.add(org)
        seen.add(identity); row['candidate_id']=str(row.get('entity_type','company'))+':'+identity
        results.append(row)
        if len(results)==limit: break
    return {'candidates':results,'candidate_count':len(results),'rejected':rejected}

import json

def handler(context):
    raw=context.get_input('research')
    if isinstance(raw,str): raw=json.loads(raw)
    found=[]
    def walk(value):
        if isinstance(value,dict):
            if 'candidate_id' in value and 'fit_claim' in value:
                evidence=[]
                for dim in ['fit','proof','insight','usefulness']:
                    if value.get(dim+'_claim') and value.get(dim+'_url'):
                        evidence.append({'id':dim,'dimension':dim,'claim':value[dim+'_claim'],'source_url':value[dim+'_url'],
                                         'source_type':value.get(dim+'_source_type','unknown'),'source_date':value.get(dim+'_date') or None,
                                         'excerpt':value.get(dim+'_excerpt',''),'strength':value.get(dim+'_strength',0),
                                         'attribution_status':'confirmed' if value.get(dim+'_attributed') else 'unclear','contradiction':False})
                found.append({k:value.get(k) for k in ['candidate_id','name','entity_type','domain','profile_url','identity_confirmed','identity_url','lane','takeaway','feature_question']} |
                             {'evidence':evidence,'disqualifiers':[] if str(value.get('disqualifiers','')).strip().lower() in ('','none','unknown') else [value['disqualifiers']],
                              'unknowns':[value.get('unknowns','')]})
            elif 'dossier_json' in value:
                item=value['dossier_json']; found.append(json.loads(item) if isinstance(item,str) else item)
            else:
                for item in value.values(): walk(item)
        elif isinstance(value,list):
            for item in value: walk(item)
    walk(raw)
    unique={row['candidate_id']:row for row in found}
    if not unique: raise ValueError('No evidence dossiers returned; inspect research node output')
    return {'dossiers_json':json.dumps(list(unique.values())),'dossiers':list(unique.values()),'dossier_count':len(unique)}

import json, math, time

DIMENSIONS=['fit','proof','insight','usefulness']
SOURCE_WEIGHT={'primary':1.0,'independent':1.0,'self_reported':0.65}

def parse(value): return json.loads(value) if isinstance(value,str) else value

def source_key(url):
    rest=str(url).split('://',1)[-1].split('#',1)[0].rstrip('/')
    parts=rest.split('/',1)
    return parts[0].lower().removeprefix('www.')+('/'+parts[1] if len(parts)>1 else '')

def ordinal(date):
    y,m,d=[int(p) for p in date.split('-')]
    leap=y%4==0 and (y%100!=0 or y%400==0)
    lengths=[31,29 if leap else 28,31,30,31,30,31,31,30,31,30,31]
    if y<1 or not 1<=m<=12 or not 1<=d<=lengths[m-1]: raise ValueError('Invalid date')
    return 365*(y-1)+(y-1)//4-(y-1)//100+(y-1)//400+sum(lengths[:m-1])+d

def quality(item,now,half_life):
    url=str(item.get('source_url',''))
    host=url.split('://',1)[-1].split('/',1)[0]
    if not url.startswith(('https://','http://')) or '.' not in host or '@' in host or item.get('attribution_status')!='confirmed': return 0
    strength=item.get('strength',0)
    if type(strength) not in (int,float) or not 0<=strength<=4: return 0
    freshness=0.65
    if item.get('source_date'):
        try:
            age=ordinal(now)-ordinal(item['source_date'])
            if age<0: return 0
            freshness=0.5**(age/half_life)
        except (ValueError,TypeError): return 0
    return (strength/4)*SOURCE_WEIGHT.get(item.get('source_type'),0.4)*(0.55+0.45*freshness)

def evidence_score(items,weights,now,half_life):
    components={k:0.0 for k in DIMENSIONS}
    for e in items:
        dim=e.get('dimension')
        if dim not in components: continue
        q=quality(e,now,half_life)
        components[dim]=max(components[dim],q)
    # Geometric aggregation penalizes missing dimensions rather than letting fame compensate.
    geometric=1.0
    for k in DIMENSIONS: geometric*=max(0.03,components[k])**weights[k]
    score=100*geometric if items else 0.0
    return score,{k:round(v*100,1) for k,v in components.items()}

def handler(context):
    icp=parse(context.get_input('icp_json')); memory=parse(context.get_input('memory_json'))
    dossiers=parse(context.get_input('dossiers_json')); audits=parse(context.get_input('audits_json'))
    flat=[]
    def collect_audits(value):
        if isinstance(value,dict):
            if 'candidate_id' in value and 'verified_ids' in value:
                flat.append({'candidate_id':value['candidate_id'],'identity_verified':value.get('identity_verified',False),
                             'verified_evidence_ids':[s.strip() for s in value.get('verified_ids','').split(',') if s.strip()],
                             'rejected_evidence_ids':[s.strip() for s in value.get('rejected_ids','').split(',') if s.strip()],
                             'contradicted_evidence_ids':[s.strip() for s in value.get('contradicted_ids','').split(',') if s.strip()],
                             'reason':value.get('reason',''),'missing_proof':value.get('missing_proof',''),'checked_urls':value.get('checked_urls','').splitlines()})
            elif 'candidate_id' in value and 'verified_evidence_ids' in value: flat.append(value)
            else:
                for v in value.values():collect_audits(v)
        elif isinstance(value,list):
            for v in value:collect_audits(v)
    collect_audits(audits);audits=flat
    audit_by_id={a['candidate_id']:a for a in audits}
    weights=icp['weights']; now=time.strftime('%Y-%m-%d',time.gmtime()); half_life=max(1,float(icp.get('freshness_half_life_days',90)))
    settings=icp.get('settings',{'minimum_score':55,'minimum_fit':40,'minimum_proof':40,'minimum_sources':2})
    ranked=[]
    for row in dossiers:
        cid=row['candidate_id']; audit=audit_by_id.get(cid,{})
        verified=set(audit.get('verified_evidence_ids',[])); rejected=set(audit.get('rejected_evidence_ids',[]))
        contradicted=set(audit.get('contradicted_evidence_ids',[]))
        evidence=[e for e in row.get('evidence',[]) if e.get('id') in verified and e.get('id') not in rejected|contradicted and not e.get('contradiction') and quality(e,now,half_life)>0]
        base,components=evidence_score(evidence,weights,now,half_life)
        penalty=min(30,10*len(contradicted)); base=max(0,base-penalty)
        urls={source_key(e['source_url']):e['source_url'].split('#')[0].rstrip('/') for e in evidence}
        identity_url=str(row.get('identity_url') or '')
        identity_key=source_key(identity_url)
        checked={source_key(u) for u in audit.get('checked_urls',[])}
        verified_identity_source=None
        if (audit.get('identity_verified') and row.get('identity_confirmed') and identity_url.startswith(('https://','http://'))
                and identity_key in checked and '.' in identity_key.split('/')[0] and '@' not in identity_key.split('/')[0]):
            verified_identity_source=identity_url
            urls[identity_key]=identity_url
        lane=row.get('lane','strategist'); arm=memory['arms'].get(lane,{'alpha':1,'beta':1,'reviews':0})
        # Beta-Bernoulli reward learning. Bounded bonus ranks qualified candidates; it cannot qualify one.
        posterior=arm['alpha']/(arm['alpha']+arm['beta'])
        learning_bonus=8*(posterior-0.5) if arm['reviews'] else 0
        uncertainty=math.sqrt(arm['alpha']*arm['beta']/((arm['alpha']+arm['beta'])**2*(arm['alpha']+arm['beta']+1)))
        prior=memory['seen'].get(cid); novelty='PREVIOUSLY_REVIEWED' if prior else 'NEW_DISCOVERY'
        holds=[]
        if not audit.get('identity_verified') or not row.get('identity_confirmed'): holds.append('Identity not independently checked by audit')
        if len(urls)<settings['minimum_sources']: holds.append('Need '+str(settings['minimum_sources'])+' verified source URLs')
        if not any(e.get('source_type')=='primary' and e.get('dimension')!='fit' for e in evidence): holds.append('Need a verified primary work artifact beyond identity/fit')
        if base<settings['minimum_score']: holds.append('Evidence score below '+str(settings['minimum_score']))
        if components['fit']<settings['minimum_fit']: holds.append('Insufficient demonstrated ICP fit')
        if components['proof']<settings['minimum_proof']: holds.append('Insufficient demonstrated proof')
        if contradicted: holds.append('Contradictory evidence needs review')
        if row.get('disqualifiers'): holds.append('ICP disqualifier present')
        decision='RESEARCH_REQUIRED' if holds else 'QUALIFIED_FOR_REVIEW'
        sensitivity=[]
        for key in sorted(urls):
            score,_=evidence_score([e for e in evidence if source_key(e['source_url'])!=key],weights,now,half_life)
            sensitivity.append({'removed_source':urls[key],'score_without_source':round(max(0,score-penalty),1)})
        worst=min(sensitivity,key=lambda x:x['score_without_source']) if sensitivity else {'removed_source':None,'score_without_source':0}
        delta=round(base-prior['score'],1) if prior else None
        result={**row,'verified_evidence':evidence,'verified_identity_source':verified_identity_source,'verified_source_count':len(urls),'unverified_count':len(row.get('evidence',[]))-len(evidence),'score':round(base,1),'components':components,
                'priority_score':round(min(100,max(0,base+learning_bonus)),1),'learning_bonus':round(learning_bonus,2),'posterior_reward_mean':round(posterior,3),
                'reward_uncertainty':round(uncertainty,3),'human_reviews_in_lane':arm['reviews'],'decision':decision,'hold_reasons':holds,
                'novelty':novelty,'score_delta':delta,'strongest_source_removed':worst,'audit':audit}
        ranked.append(result)
        memory['seen'][cid]={'name':row['name'],'lane':lane,'score':round(base,1),'last_researched_at':now,'source_urls':sorted(urls.values())}
    ranked.sort(key=lambda x:(x['decision']=='QUALIFIED_FOR_REVIEW',x['priority_score']),reverse=True)
    qualified=[r for r in ranked if r['decision']=='QUALIFIED_FOR_REVIEW']
    explore=max(ranked,key=lambda r:r['reward_uncertainty'],default=None)
    return {'ranking_json':json.dumps(ranked),'memory_json':json.dumps(memory),'qualified_count':len(qualified),'researched_count':len(ranked),
            'research_required_count':len(ranked)-len(qualified),'exploration_candidate':explore['name'] if explore else '',
            'learning_state':'REVIEW_LEARNING' if memory['processed_feedback'] else 'COLD_START',
            'score_method':'Weighted geometric evidence score; recency decay; contradiction penalty; leave-one-source-out sensitivity; bounded Beta-Bernoulli feedback bonus. Scores are heuristics, not probabilities.',
            'next_run_instruction':'Carry memory_json from this run record into the next run with the exact same focus. Add feedback_json only for real human ratings. Workflow does not retrieve previous runs automatically.'}
